package com.yihe.framework.ehr;
import java.util.*;import java.net.URLEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
/** Read-only overview. Existing execution queues remain authoritative. */
@Service public class AgentOverviewService {
 final EhrRepository db;final DigitalWorkerTaskHub hub;static final List<String>WORKERS=Arrays.asList("archive","assess","follow","plan","care"),STATES=Arrays.asList("queued","in_progress","pending_review","completed","failed","cancelled","unknown"),SOURCES=Arrays.asList("assignment","ocr","alert","exam","comprehensive","chronic","occupational","psychological","psych_workflow","collaboration");
 public AgentOverviewService(EhrRepository db,DigitalWorkerTaskHub hub){this.db=db;this.hub=hub;}
 void allow(EhrActor a){require(!a.mobile&&a.doctor,403,"AI数字员工中心仅供当前单位授权医生使用");}
 static String s(String x){return "CONVERT("+x+" USING utf8mb4) COLLATE utf8mb4_unicode_ci";}
 String projection(String...v){String[]names={"id","source","worker","type","title","status","nativeStatus","priority","recordId","memberCode","memberName"};List<String>l=new ArrayList<>();for(int i=0;i<names.length;i++)l.add(s(v[i])+" "+names[i]);return String.join(",",l);}
 String from(EhrActor a,List<Object>args){allow(a);String base=hub.union(a,args);base=base.substring(1,base.lastIndexOf(") hub"));String[]tables={"a_ai_exam_tasks","a_comprehensive_analyses","a_chronic_risk_tasks","a_occupational_risk_tasks","a_psych_assessment_tasks"},sources={"exam","comprehensive","chronic","occupational","psychological"},titles={"AI体检评估","综合健康评估","慢性病风险评估","职业健康风险评估","心理健康评估"};for(int i=0;i<tables.length;i++){boolean comp=i==1;String key=comp?"t.analysis_id":"t.task_id",raw=comp?"t.analysis_state":"t.ai_state",review=comp?"EXISTS(SELECT 1 FROM a_comprehensive_reviews v WHERE v.analysis_id=t.analysis_id AND v.scope_code=t.scope_code AND v.data_mode=t.data_mode)":"t.review_state='confirmed'",state="CASE WHEN "+raw+"='completed' THEN CASE WHEN "+review+" THEN 'completed' ELSE 'pending_review' END WHEN "+raw+"='running' THEN 'in_progress' WHEN "+raw+"='pending' THEN CASE WHEN t.lease_until>UTC_TIMESTAMP(6) THEN 'in_progress' ELSE 'queued' END WHEN "+raw+" IN ('queued','failed','cancelled') THEN "+raw+" ELSE 'unknown' END";base+=" UNION ALL SELECT "+projection(key,"'"+sources[i]+"'",i==4?"'care'":"'assess'","'"+sources[i]+"'","'"+titles[i]+"'",state,raw,"'normal'","t.record_id","p.employee_no","p.employee_name")+",t.created_at createdAt,"+(comp?"COALESCE(t.finished_at,t.created_at)":"COALESCE(t.reviewed_at,t.finished_at,t.created_at)")+" updatedAt,NULL percent,CASE WHEN p.employee_id IS NULL THEN 0 ELSE 1 END canOpen FROM "+tables[i]+" t LEFT JOIN a_health_records r ON r.record_id=t.record_id AND r.scope_code=t.scope_code AND r.data_mode=t.data_mode LEFT JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode AND p.deleted_at IS NULL WHERE t.scope_code=? AND t.data_mode=?";args.add(a.scope);args.add(a.mode);}base+=" UNION ALL SELECT "+projection("t.item_id","'psych_workflow'","'care'","t.item_kind","t.title","t.task_status","t.task_status","t.priority","t.record_id","p.employee_no","p.employee_name")+",t.created_at createdAt,t.updated_at updatedAt,NULL percent,CASE WHEN p.employee_id IS NULL THEN 0 ELSE 1 END canOpen FROM a_psych_worker_items t LEFT JOIN a_health_records r ON r.record_id=t.record_id AND r.scope_code=t.scope_code AND r.data_mode=t.data_mode LEFT JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode AND p.deleted_at IS NULL WHERE t.scope_code=? AND t.data_mode=?";args.add(a.scope);args.add(a.mode);
base+=" UNION ALL SELECT "+projection("t.order_id","'collaboration'","t.target_worker","'collaboration_order'","t.title","CASE WHEN t.order_state IN ('claimed','in_progress') THEN 'in_progress' WHEN t.order_state IN ('awaiting_acceptance','returned') THEN 'pending_review' WHEN t.order_state IN ('completed','failed','cancelled') THEN t.order_state ELSE 'queued' END","t.order_state","t.priority","t.record_id","p.employee_no","p.employee_name")+",t.created_at createdAt,t.updated_at updatedAt,NULL percent,CASE WHEN p.employee_id IS NULL THEN 0 ELSE 1 END canOpen FROM a_worker_orders t JOIN a_health_records r ON r.record_id=t.record_id AND r.scope_code=t.scope_code AND r.data_mode=t.data_mode LEFT JOIN a_employee_roster_profiles p ON p.employee_id=r.employee_id AND p.scope_code=r.scope_code AND p.data_mode=r.data_mode AND p.deleted_at IS NULL WHERE t.scope_code=? AND t.data_mode=?";args.add(a.scope);args.add(a.mode);
return "("+base+") tasks";}
 static String today(){return "CONVERT_TZ(DATE(CONVERT_TZ(UTC_TIMESTAMP(),'+00:00','+08:00')),'+08:00','+00:00')";}
 static String day(){return "DATE(CONVERT_TZ(createdAt,'+00:00','+08:00'))";}
 Map<String,Object>empty(){Map<String,Object>m=map("total",0L);for(String s:STATES)m.put(s,0L);return m;}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Map<String,Object>overview(EhrActor a){List<Object>args=new ArrayList<>();String from=from(a,args),today=" WHERE createdAt>="+today()+" AND createdAt<DATE_ADD("+today()+",INTERVAL 1 DAY)";Map<String,Object>summary=empty(),workers=new LinkedHashMap<>();for(String w:WORKERS)workers.put(w,empty());for(Map<String,Object>r:db.all("SELECT worker,status,COUNT(*) n FROM "+from+today+" GROUP BY worker,status",args.toArray())){String state=text(r,"status");long n=((Number)r.get("n")).longValue();for(Map<String,Object>m:Arrays.asList(summary,(Map<String,Object>)workers.get(r.get("worker")))){m.put("total",((Number)m.get("total")).longValue()+n);m.put(state,((Number)m.get(state)).longValue()+n);}}
 List<Map<String,Object>>backlog=db.all("SELECT worker,status,COUNT(*) count FROM "+from+" WHERE status IN ('queued','in_progress','pending_review') GROUP BY worker,status",args.toArray()),trend=db.all("SELECT "+day()+" day,COUNT(*) total,SUM(status='completed') completed FROM "+from+" WHERE createdAt>=DATE_SUB("+today()+",INTERVAL 6 DAY) AND createdAt<DATE_ADD("+today()+",INTERVAL 1 DAY) GROUP BY "+day()+" ORDER BY day",args.toArray()),feed=db.all("SELECT * FROM "+from+" ORDER BY updatedAt DESC,source,id DESC LIMIT 5",args.toArray());for(Map<String,Object>r:feed)decorate(a,r);return map("summary",summary,"byWorker",workers,"backlog",backlog,"trend",trend,"feed",feed,"tokenUsage",null,"tokenUsageAvailable",false,"tokenUsageNote","现有任务未保存完整用量计量","capturedAt",now(),"timezone","Asia/Shanghai","cohort","created_today","sources",SOURCES);}
 String filter(Map<String,String>q,List<Object>args){String where=" WHERE 1=1";String priority=q.getOrDefault("priority","");if(!priority.isEmpty()){require(priority.equals("high_or_urgent"),422,"Invalid priority filter");where+=" AND priority IN ('high','urgent')";}String period=q.getOrDefault("period","today");require(Arrays.asList("today","all").contains(period),422,"时间范围无效");if(period.equals("today"))where+=" AND createdAt>="+today()+" AND createdAt<DATE_ADD("+today()+",INTERVAL 1 DAY)";for(String key:Arrays.asList("worker","source","status","type")){String v=q.getOrDefault(key,"");if(v.isEmpty()||v.equals("all"))continue;require((key.equals("worker")?WORKERS:key.equals("source")?SOURCES:key.equals("type")?Arrays.asList("visit_invitation","routine_followup","alert_handling","abnormal_followup","plan_adjustment","report_interpretation","archive_completion","assessment","complaint_followup","report_ocr","indicator_alert","exam","comprehensive","chronic","occupational","psychological","response_review","assessment_assignment","reassessment_request","collaboration_order"):STATES).contains(v),422,"任务筛选无效");where+=" AND "+key+"=?";args.add(v);}String search=q.getOrDefault("search","").trim();require(search.length()<=100,422,"搜索最多100字");if(!search.isEmpty()){where+=" AND (title LIKE ? ESCAPE '!' OR memberCode LIKE ? ESCAPE '!' OR memberName LIKE ? ESCAPE '!' OR id LIKE ? ESCAPE '!')";String term="%"+EhrService.like(search)+"%";args.addAll(Arrays.asList(term,term,term,term));}return where;}
 int positive(String s,int fallback,int max){try{int n=s==null?fallback:Integer.parseInt(s);require(n>=1&&n<=max,422,"分页参数无效");return n;}catch(NumberFormatException e){throw new EhrException(422,"分页参数无效");}}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)public Map<String,Object>list(EhrActor a,Map<String,String>q){List<Object>args=new ArrayList<>();String from=from(a,args),where=filter(q,args);long total=db.count("SELECT COUNT(*) FROM "+from+where,args.toArray());int page=positive(q.get("page"),1,100000),limit=positive(q.get("limit"),10,100);args.add(limit);args.add((page-1)*limit);List<Map<String,Object>>items=db.all("SELECT * FROM "+from+where+" ORDER BY updatedAt DESC,source,id DESC LIMIT ? OFFSET ?",args.toArray());for(Map<String,Object>r:items)decorate(a,r);return map("total",total,"items",items,"page",page,"limit",limit);}
 String enc(Object v){try{return URLEncoder.encode(str(v),"UTF-8");}catch(Exception e){throw new IllegalArgumentException(e);}}
 void decorate(EhrActor a,Map<String,Object>r){String source=text(r,"source"),href=null,record=text(r,"recordId");if(num(r.get("canOpen"))==0){r.put("href",null);return;}if(source.equals("psych_workflow")||source.equals("collaboration"))href="/assets/agents/"+(source.equals("psych_workflow")?"care":"dispatch")+".html?"+(source.equals("psych_workflow")?"psychItem":"order")+"="+enc(r.get("id"));else if(Arrays.asList("assignment","ocr","alert").contains(source))href="/manage/digital-workers/"+(source.equals("assignment")?"workbench":source.equals("ocr")?"records":"dispatch")+"?worker="+enc(r.get("worker"))+"&"+(source.equals("assignment")?"task":source.equals("ocr")?"task":"alert")+"="+enc(r.get("id"));else if(source.equals("comprehensive"))href="/assets/assessment/comprehensive.html?record="+enc(record)+"&analysis="+enc(r.get("id"));else if(source.equals("exam")){Map<String,Object>t=db.one("SELECT report_id FROM a_ai_exam_tasks WHERE task_id=? AND scope_code=? AND data_mode=?",r.get("id"),a.scope,a.mode);if(t!=null)href="/assets/assessment/exam.html?search="+enc(t.get("report_id"));}else href="/assets/assessment/"+(source.equals("chronic")?"chronic-risk":source.equals("occupational")?"occupational-risk":"psychological")+".html?search="+enc(r.get("memberCode"));r.put("href",href);}
}
